import express from 'express';
import path from 'path';
import fs from 'fs';
import JSZip from 'jszip';
import { createServer as createViteServer } from 'vite';
import { getWeatherData } from './src/server/weatherService';

const EXCLUDED_PATHS = ['node_modules', 'dist', '.git', '.DS_Store', 'package-lock.json'];

function getAllProjectFiles(dir: string, baseDir: string = dir): { relativePath: string; fullPath: string }[] {
  let results: { relativePath: string; fullPath: string }[] = [];
  const list = fs.readdirSync(dir);
  for (const file of list) {
    if (EXCLUDED_PATHS.includes(file)) continue;
    const fullPath = path.join(dir, file);
    const relativePath = path.relative(baseDir, fullPath);
    const stat = fs.statSync(fullPath);
    if (stat && stat.isDirectory()) {
      results = results.concat(getAllProjectFiles(fullPath, baseDir));
    } else {
      results.push({ relativePath, fullPath });
    }
  }
  return results;
}

async function startServer() {
  const app = express();
  const PORT = 3000;

  app.use(express.json());

  // API Route: Weather
  app.get('/api/weather', async (req, res) => {
    const force = req.query.force === 'true';
    const data = await getWeatherData(force);
    res.json(data);
  });

  // API Route: Get project file list & contents for Code Explorer
  app.get('/api/project-files', (req, res) => {
    try {
      const rootDir = process.cwd();
      const fileList = getAllProjectFiles(rootDir);
      const filesData = fileList.map((f) => {
        let content = '';
        try {
          content = fs.readFileSync(f.fullPath, 'utf-8');
        } catch {
          content = '[Binary or Unreadable Content]';
        }
        return {
          path: f.relativePath,
          content,
          size: fs.statSync(f.fullPath).size,
        };
      });
      res.json({ success: true, files: filesData });
    } catch (err: any) {
      res.status(500).json({ success: false, error: err.message });
    }
  });

  // API Route: Download complete project source code as ZIP
  app.get('/api/download-zip', async (req, res) => {
    try {
      const zip = new JSZip();
      const rootDir = process.cwd();
      const files = getAllProjectFiles(rootDir);

      for (const f of files) {
        try {
          const fileData = fs.readFileSync(f.fullPath);
          zip.file(f.relativePath, fileData);
        } catch (e) {
          console.error(`Failed to include file ${f.relativePath}:`, e);
        }
      }

      const buffer = await zip.generateAsync({ type: 'nodebuffer', compression: 'DEFLATE' });
      res.setHeader('Content-Type', 'application/zip');
      res.setHeader('Content-Disposition', 'attachment; filename="D-Curb-Guardian-SourceCode.zip"');
      res.send(buffer);
    } catch (err: any) {
      console.error('ZIP generation error:', err);
      res.status(500).json({ error: 'Failed to generate ZIP archive' });
    }
  });

  // Health check
  app.get('/api/health', (req, res) => {
    res.json({ status: 'ok', serverTime: new Date().toISOString() });
  });

  // Vite Middleware in Dev Mode vs Static Serve in Prod Mode
  if (process.env.NODE_ENV !== 'production') {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), 'dist');
    app.use(express.static(distPath));
    app.get('*', (req, res) => {
      res.sendFile(path.join(distPath, 'index.html'));
    });
  }

  app.listen(PORT, '0.0.0.0', () => {
    console.log(`D-Curb Guardian server running on http://0.0.0.0:${PORT}`);
  });
}

startServer();
