import fs from 'fs';
import path from 'path';

export interface TimeBlockWeather {
  score: number;
  status: '배송시간 조정 검토' | '주의 운영' | '정상 운영';
  reason: string;
  maxRainProb: number;
  maxPrecipMm: number;
  maxTempC: number;
}

export interface DongWeatherForecast {
  dongCode: string;
  dong: string;
  gu: string;
  gridId: string;
  forecast: {
    [dateStr: string]: {
      [timeBlockKey: string]: TimeBlockWeather;
    };
  };
}

export interface WeatherApiResponse {
  fetchedAt: string;
  stale: boolean;
  error?: string;
  dates: string[];
  timeBlocks: string[];
  byDongCode: {
    [dongCode: string]: DongWeatherForecast;
  };
}

const CACHE_TTL_MS = 30 * 60 * 1000; // 30 minutes
let memoryCache: WeatherApiResponse | null = null;
let lastFetchTimestamp: number = 0;

function readJsonFile<T>(filename: string): T {
  const primaryPath = path.join(process.cwd(), 'data', filename);
  const fallbackPath = path.join(process.cwd(), filename);

  let targetPath = primaryPath;
  if (!fs.existsSync(primaryPath) && fs.existsSync(fallbackPath)) {
    targetPath = fallbackPath;
  }

  const raw = fs.readFileSync(targetPath, 'utf-8');
  return JSON.parse(raw);
}

export async function getWeatherData(forceRefresh = false): Promise<WeatherApiResponse> {
  const now = Date.now();

  if (!forceRefresh && memoryCache && now - lastFetchTimestamp < CACHE_TTL_MS) {
    return memoryCache;
  }

  try {
    const weatherGridData = readJsonFile<{ grids: Array<{ gridId: string; lat: number; lon: number; dongs: string[] }> }>('weather_grid.json');
    const dongGeoData = readJsonFile<{ dongs: Array<{ dongCode: string; gu: string; dong: string; lat: number; lon: number; gridId: string }> }>('dong_geo.json');

    const grids = weatherGridData.grids;
    const lats = grids.map((g) => g.lat).join(',');
    const lons = grids.map((g) => g.lon).join(',');

    const apiUrl = `https://api.open-meteo.com/v1/forecast?latitude=${lats}&longitude=${lons}&hourly=temperature_2m,precipitation,precipitation_probability,wind_speed_10m,wind_gusts_10m&timezone=Asia/Seoul&forecast_days=7`;

    const response = await fetch(apiUrl, { signal: AbortSignal.timeout(8000) });
    if (!response.ok) {
      throw new Error(`Open-Meteo returned HTTP ${response.status}`);
    }

    const rawResult = await response.json();
    const forecastList: any[] = Array.isArray(rawResult) ? rawResult : [rawResult];

    const TIME_BLOCKS = [
      { id: '07~10', from: 7, to: 10 },
      { id: '10~12', from: 10, to: 12 },
      { id: '12~14', from: 12, to: 14 },
      { id: '14~17', from: 14, to: 17 },
      { id: '17~20', from: 17, to: 20 },
      { id: '20~23', from: 20, to: 23 },
    ];

    // GridId -> forecast per date and block
    const gridForecasts: Record<string, Record<string, Record<string, TimeBlockWeather>>> = {};
    const dateSet = new Set<string>();

    grids.forEach((grid, index) => {
      const locForecast = forecastList[index] || forecastList[0];
      const hourly = locForecast?.hourly;
      if (!hourly || !hourly.time) return;

      const times: string[] = hourly.time;
      const temps: number[] = hourly.temperature_2m || [];
      const precips: number[] = hourly.precipitation || [];
      const probs: number[] = hourly.precipitation_probability || [];

      gridForecasts[grid.gridId] = {};

      for (let i = 0; i < times.length; i++) {
        const timeStr = times[i]; // "2026-07-25T07:00"
        const dateStr = timeStr.slice(0, 10);
        const hour = parseInt(timeStr.slice(11, 13), 10);
        dateSet.add(dateStr);

        if (!gridForecasts[grid.gridId][dateStr]) {
          gridForecasts[grid.gridId][dateStr] = {};
        }

        const block = TIME_BLOCKS.find((b) => hour >= b.from && hour < b.to);
        if (!block) continue;

        if (!gridForecasts[grid.gridId][dateStr][block.id]) {
          gridForecasts[grid.gridId][dateStr][block.id] = {
            score: 0,
            status: '정상 운영',
            reason: '기상 위험 낮음',
            maxRainProb: 0,
            maxPrecipMm: 0,
            maxTempC: -99,
          };
        }

        const currentBlock = gridForecasts[grid.gridId][dateStr][block.id];
        currentBlock.maxRainProb = Math.max(currentBlock.maxRainProb, probs[i] || 0);
        currentBlock.maxPrecipMm = Math.max(currentBlock.maxPrecipMm, precips[i] || 0);
        currentBlock.maxTempC = Math.max(currentBlock.maxTempC, temps[i] || 0);
      }

      // Compute scores after iterating all hours for this grid
      Object.keys(gridForecasts[grid.gridId]).forEach((dStr) => {
        TIME_BLOCKS.forEach((block) => {
          const item = gridForecasts[grid.gridId][dStr][block.id];
          if (!item) return;

          let rainScore = 0;
          let rainReason = '';
          if (item.maxRainProb >= 80) {
            rainScore = 8;
            rainReason = '강수확률 80% 이상';
          } else if (item.maxRainProb >= 60) {
            rainScore = 5;
            rainReason = '강수확률 60% 이상';
          } else if (item.maxRainProb >= 40) {
            rainScore = 3;
            rainReason = '강수확률 40% 이상';
          }

          let precipScore = 0;
          let precipReason = '';
          if (item.maxPrecipMm > 0) {
            precipScore = 3;
            precipReason = '강수 예보';
          }

          let tempScore = 0;
          let tempReason = '';
          if (item.maxTempC >= 33) {
            tempScore = 5;
            tempReason = '고온 위험';
          }

          item.score = rainScore + precipScore + tempScore;

          const reasons: string[] = [];
          if (rainReason) reasons.push(rainReason);
          if (precipReason) reasons.push(precipReason);
          if (tempReason) reasons.push(tempReason);

          item.reason = reasons.length > 0 ? reasons.join(' / ') : '기상 위험 낮음';

          if (item.score >= 10) {
            item.status = '배송시간 조정 검토';
          } else if (item.score >= 5) {
            item.status = '주의 운영';
          } else {
            item.status = '정상 운영';
          }
        });
      });
    });

    // Map to all 82 dongs
    const byDongCode: Record<string, DongWeatherForecast> = {};
    const sortedDates = Array.from(dateSet).sort();

    dongGeoData.dongs.forEach((dong) => {
      const gridFc = gridForecasts[dong.gridId] || {};
      byDongCode[dong.dongCode] = {
        dongCode: dong.dongCode,
        dong: dong.dong,
        gu: dong.gu,
        gridId: dong.gridId,
        forecast: gridFc,
      };
    });

    const payload: WeatherApiResponse = {
      fetchedAt: new Date().toISOString(),
      stale: false,
      dates: sortedDates,
      timeBlocks: ['07~10', '10~12', '12~14', '14~17', '17~20', '20~23'],
      byDongCode,
    };

    memoryCache = payload;
    lastFetchTimestamp = now;
    return payload;
  } catch (err: any) {
    console.error('Failed to fetch Open-Meteo weather:', err);

    if (memoryCache) {
      return {
        ...memoryCache,
        stale: true,
      };
    }

    // Return safe fallback if no memory cache available
    const fallbackDates = [
      new Date().toISOString().slice(0, 10),
      new Date(Date.now() + 86400000).toISOString().slice(0, 10),
      new Date(Date.now() + 86400000 * 2).toISOString().slice(0, 10),
      new Date(Date.now() + 86400000 * 3).toISOString().slice(0, 10),
      new Date(Date.now() + 86400000 * 4).toISOString().slice(0, 10),
      new Date(Date.now() + 86400000 * 5).toISOString().slice(0, 10),
      new Date(Date.now() + 86400000 * 6).toISOString().slice(0, 10),
    ];

    return {
      fetchedAt: new Date().toISOString(),
      stale: true,
      error: '기상 데이터를 불러오지 못했습니다',
      dates: fallbackDates,
      timeBlocks: ['07~10', '10~12', '12~14', '14~17', '17~20', '20~23'],
      byDongCode: {},
    };
  }
}
